````
def product_except_self(arr):
    """
    Return a list where result[i] is the product of all elements
    in arr except arr[i].

    Handles three cases:
    1. No zeros
    2. Exactly one zero
    3. More than one zero
    """
    zero_count = 0
    product_nonzero = 1

    # First pass: count zeros and multiply all nonzero elements
    for x in arr:
        if x == 0:
            zero_count += 1
        else:
            product_nonzero *= x

    result = []

    # Case 1: More than one zero
    if zero_count > 1:
        result = [0] * len(arr)

    # Case 2: Exactly one zero
    elif zero_count == 1:
        for x in arr:
            if x == 0:
                result.append(product_nonzero)
            else:
                result.append(0)

    # Case 3: No zeros
    else:
        for x in arr:
            result.append(product_nonzero // x)

    return result

